                outside.add((r, c))
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and (nr, nc) not in outside):
                outside.add((nr, nc))
                stack.append((nr, nc))

    inside = {(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == 0 and (r, c) not in outside}

    # Color interior zeroes touching the outline.
    outline = set()
    for r, c in inside:
        if any(0 <= r + dr < h and 0 <= c + dc < w
               and grid[r + dr][c + dc] == 1
               for dr in (-1, 0, 1) for dc in (-1, 0, 1)):
            out[r][c] = 3
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                        outline.add((nr, nc))

    # Color the exterior halo around the enclosing outline.
    halo = set()
    for r, c in outline:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                        and (nr, nc) in outside):
                    out[nr][nc] = 2
                    halo.add((nr, nc))

    # Some interior edge cells connect to the exterior through a narrow opening;
    # extend the interior coloring along the outline, but not into the halo.
    additions = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) not in outside or (r, c) in halo:
                continue
            near_three = any(
                0 <= r + dr < h and 0 <= c + dc < w
                and out[r + dr][c + dc] == 3
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))
