            near_one = any(
                0 <= r + dr < h and 0 <= c + dc < w
                and grid[r + dr][c + dc] == 1
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))
            )
            if near_three and near_one:
                additions.add((r, c))
    for r, c in additions:
        out[r][c] = 3

    return out
